#!/bin/bash
set -euo pipefail

MAX_PARALLEL_JOBS=32
POLL_SECONDS=30

active_exp_jobs() {
  squeue -h -u "$USER" -t PD,R,CF,CG -o "%.200j" | awk '$1 ~ /^Exp5_/ {n++} END {print n+0}'
}

submit_when_slot_free() {
  local slurm_file="$1"
  while [ "$(active_exp_jobs)" -ge "$MAX_PARALLEL_JOBS" ]; do
    sleep "$POLL_SECONDS"
  done
  sbatch "$slurm_file"
}

